SELECT su_name, COUNT(*) AS numwait FROM tpcch.supplier, tpcch.orderline AS l1, order_view, tpcch.stock, tpcch.nation WHERE ol_o_id = o_id AND ol_w_id = o_w_id AND ol_d_id = o_d_id AND ol_w_id = s_w_id AND ol_i_id = s_i_id AND s_su_suppkey = su_suppkey AND l1.ol_delivery_d > o_entry_d AND NOT EXISTS(SELECT * FROM tpcch.orderline AS l2 WHERE l2.ol_o_id = l1.ol_o_id AND l2.ol_w_id = l1.ol_w_id AND l2.ol_d_id = l1.ol_d_id AND l2.ol_delivery_d > l1.ol_delivery_d) AND su_nationkey = n_nationkey AND n_name = 'GERMANY' GROUP BY su_name ORDER BY numwait DESC, su_name;
